resources.text:
resource "aws_lambda_function" "worker" {
  provider      = aws.west
  function_name = "orders-worker"
  runtime       = "python3.12"
  environment {
    variables = {
      DB_HOST = aws_db_instance.orders.address
      QUEUE   = "${aws_sqs_queue.jobs.url}"
    }
  }
}

modules.text:
module "db" {
  source = "./modules/db"
  name   = local.name
  vpc_id = data.aws_vpc.default.id
}

terraform.text:
terraform {
  required_version = ">= 1.6"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40"
    }
    google = {
      source  = "hashicorp/google"
      version = "~> 6.0"
    }
    random = ">= 3.1"
  }

  backend "s3" {
    bucket = "orders-state"
    key    = "prod/terraform.tfstate"
  }
}

arguments.text:
required_providers {
    aws = {
      source  = "hashicorp/aws"
